#define MOD 1000000007LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

typedef struct {
    int n;
    ll *bit;
} BIT;

static void bit_init(BIT *b, int n) {
    b->n = n;
    b->bit = (ll*)calloc(n + 2, sizeof(ll));
}

static void bit_add(BIT *b, int idx, ll val) {
    while (idx <= b->n) {
        b->bit[idx] += val;
        if (b->bit[idx] >= MOD) b->bit[idx] -= MOD;
        idx += idx & -idx;
    }
}

static ll bit_sum(BIT *b, int idx) {
    ll r = 0;
    while (idx > 0) {
        r += b->bit[idx];
        if (r >= MOD) r -= MOD;
        idx -= idx & -idx;
    }
    return r;
}

static ll bit_range(BIT *b, int l, int r) {
    if (r < l) return 0;
    ll res = bit_sum(b, r) - bit_sum(b, l - 1);
    if (res < 0) res += MOD;
    return res;
}

