                ll sumY = 0;
                {
                    /* Current missing set values are exactly those in bitMissCnt.
                       Since we only remove values, and missing[] is sorted, iterate once over all initial missing
                       and test current presence by rank difference via BIT range.
                       Total O(K log N), acceptable.
                    */
                    for (int t = 1; t <= K; t++) {
