                            sumY += y;
                            if (sumY >= MOD) sumY -= MOD;
                        }
                    }
                }
                sumYminus1 = (sumY - z) % MOD;
                if (sumYminus1 < 0) sumYminus1 += MOD;

                /* sum over current missing y of usedKnownLess(y-1)
