public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        boolean[] used = new boolean[N + 1];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            if (A[i] != 0) used[A[i]] = true;
        }

        // Precompute factorials
        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        // Count forgotten values
        int unknownCount = 0;
        for (int i = 0; i < N; i++) {
            if (A[i] == 0) unknownCount++;
        }

        long result = 0;
        long prefixPerms = 1; // number of ways to fill known prefix positions
        int usedCount = 0;

        for (int i = 0; i < N; i++) {
            if (A[i] == 0) {
                // Try each possible forgotten value
                int possible = 0;
                for (int v = 1; v <= N; v++) {
                    if (!used[v]) possible++;
                }
                // For each such value, number of permutations for rest = fact[unknownCount - 1]
                long add = (long) possible * fact[unknownCount - 1] % MOD;
                result = (result + prefixPerms * add) % MOD;
                // Fix one unknown as "used" for further steps
                unknownCount--;
            } else {
                // Count how many smaller unused values exist
                int smaller = 0;
                for (int v = 1; v < A[i]; v++) {
                    if (!used[v]) smaller++;
                }
                long add = (long) smaller * fact[unknownCount] % MOD;
                result = (result + prefixPerms * add) % MOD;
                used[A[i]] = true;
                usedCount++;
            }
        }

        // Add 1 for the permutation itself (page number starts at 1)
        result = (result + 1) % MOD;
        System.out.println(result);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

