public class Main {
    static final long MOD = 1_000_000_007;
    static int N;
    static int[] fixed;
    static long[] fact;
    static long[][] dpCount, dpContrib;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        fixed = new int[N];
        for (int i = 0; i < N; i++) fixed[i] = sc.nextInt();
        fact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        dpCount = new long[N][1 << N];
        dpContrib = new long[N][1 << N];
        for (long[] a : dpCount) Arrays.fill(a, -1);
        long[] res = solve(0, 0);
        System.out.println((res[0] + res[1]) % MOD);
    }

    static long[] solve(int i, int mask) {
        if (i == N) return new long[]{1, 0};
        if (dpCount[i][mask] != -1) return new long[]{dpCount[i][mask], dpContrib[i][mask]};
        long count = 0, contrib = 0;
        int[] candidates = fixed[i] == 0 ? null : new int[]{fixed[i]};
        if (fixed[i] == 0) {
            for (int v = 1; v <= N; v++) {
                if ((mask & (1 << (v-1))) != 0) continue;
                int rank = Integer.bitCount(mask ^ ((1<<v)-1) ^ (mask & ~((1<<v)-1))) ; // bits < v not in mask
                rank = v - 1 - Integer.bitCount(mask & ((1<<(v-1))-1));
                long[] sub = solve(i+1, mask | (1<<(v-1)));
                count = (count + sub[0]) % MOD;
                contrib = (contrib + sub[1] + (long)rank % MOD * fact[N-i-1] % MOD * sub[0]) % MOD;
            }
        } else {
            int v = fixed[i];
            if ((mask & (1<<(v-1))) == 0) {
                int rank = v - 1 - Integer.bitCount(mask & ((1<<(v-1))-1));
                long[] sub = solve(i+1, mask | (1<<(v-1)));
                count = sub[0]; contrib = (sub[1] + (long)rank * fact[N-i-1] % MOD * sub[0]) % MOD;
            }
        }
        dpCount[i][mask] = count; dpContrib[i][mask] = contrib;
        return new long[]{count, contrib};
    }
}

