/*
 *  Sum of lexicographical ranks (1-indexed) of all permutations consistent with
 *  a partially forgotten permutation.
 *
 *  Let A[1..N], where 0 means unknown, otherwise fixed value.
 *  We need:
 *    sum over all valid completions P of rank(P)
 *  modulo MOD.
 *
 *  Rank(P) = 1 + sum_{i=1..N} cnt_i * (N-i)!
 *  where cnt_i = number of unused values smaller than P_i before choosing P_i.
 *
 *  So total answer:
 *    M + sum_i (N-i)! * sum_over_completions(cnt_i)
 *  where M = number of valid completions = K! and K = number of zeros.
 *
 *  We compute contribution per position.
 *
 *  Cases:
 *  1) A[i] fixed = x:
 *     cnt_i depends on how many smaller unused values remain before i.
 *     Split smaller missing values and smaller fixed values appearing later.
 *     If t = #missing values < x, and f = #fixed values < x appearing after i,
 *     then over all completions:
 *        sum cnt_i = K! * f + (K! / K) * t * K  ? actually each missing y<x
 *     contributes probability of being unused before i = (#zeros before i)/K.
 *     Hence total from missing smaller values:
 *        t * zerosBefore(i) * (K-1)!   (for K>0)
 *
 *     So:
 *        totalCnt = K! * f + t * zerosBefore * (K-1)!
 *
 *  2) A[i] = 0:
 *     Let B = zeros before i, Aft = zeros after i, so K = B+1+Aft.
 *     For a chosen missing value y at i:
 *       cnt_i = (#fixed < y after i?) no, fixed smaller unused before i means
 *               smaller fixed values that appear after i, plus smaller missing
 *               values not used in previous zero positions.
 *     Sum over all completions can be derived by linearity over pairs.
 *
 *     Let m be number of missing values.
 *     For each missing y:
 *       - each fixed z<y appearing after i always contributes when y is placed at i.
 *         Number of completions with y at i is (K-1)!.
 *       - each other missing z<y contributes iff z is not used before i.
 *         Among permutations of missing numbers over zero slots with y fixed at i,
 *         probability z is after i = Aft / (K-1), so count = Aft * (K-2)!.
 *
 *     Therefore:
 *       sum cnt_i over all completions =
 *         (K-1)! * sum_y fixedSmallerAfter(y)
 *         + Aft * (K-2)! * C(K,2)
 *
 *     where y ranges over missing values.
 *
 *     Now sum_y fixedSmallerAfter(y):
 *       For each fixed value z appearing after i, count missing y > z.
 *       If missGreaterThan(z) = K - (#missing <= z), sum over fixed after i.
 *
 *  We precompute:
 *    - missing prefix counts by value
 *    - fixed prefix counts by value using Fenwick over values while scanning positions
 *    - number of fixed smaller after each position for a fixed x
 *    - for zero position, sum over fixed-after values of missGreaterThan(z)
 *
 *  To get for each position i with zero:
 *    S_i = sum_{fixed z after i} (number of missing values > z)
 *  Scan from right to left maintaining count of fixed values by exact value.
 *  Need sum cntVal[z] * missGreaterThan(z).
 *
 *  Complexity O(N log N).
 */

public class Main {
    static final long MOD = 1_000_000_007L;

    static class Fenwick {
        int n;
        long[] bit;
        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }
        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += val;
        }
        long sum(int idx) {
            long r = 0;
            for (int i = idx; i > 0; i -= i & -i) r += bit[i];
            return r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] a = new int[N + 1];
        boolean[] used = new boolean[N + 1];
        int K = 0;
        for (int i = 1; i <= N; i++) {
            a[i] = fs.nextInt();
            if (a[i] == 0) K++;
            else used[a[i]] = true;
        }

        boolean[] missing = new boolean[N + 1];
        int[] missPrefix = new int[N + 1];
        for (int v = 1; v <= N; v++) {
            missing[v] = !used[v];
            missPrefix[v] = missPrefix[v - 1] + (missing[v] ? 1 : 0);
        }

        long[] fact = new long[Math.max(2, N + 1)];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;

        int[] zerosBefore = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            zerosBefore[i] = zerosBefore[i - 1] + (a[i] == 0 ? 1 : 0);
        }

        long ans = fact[K]; // +1 term in rank for each completion

        // For fixed positions, need #fixed smaller values appearing after i.
        Fenwick fwLeft = new Fenwick(N);
        long[] fixedContribution = new long[N + 1];

        // We can get fixed smaller after i as total fixed smaller - fixed smaller before i.
        int[] totalFixedLess = new int[N + 1];
        int seenFixed = 0;
        for (int v = 1; v <= N; v++) {
            totalFixedLess[v] = totalFixedLess[v - 1] + (used[v] ? 1 : 0);
        }

        for (int i = 1; i <= N; i++) {
            if (a[i] != 0) {
                int x = a[i];
                long fixedSmallerBefore = fwLeft.sum(x - 1);
                long totalFixedSmaller = totalFixedLess[x - 1];
                long fixedSmallerAfter = totalFixedSmaller - fixedSmallerBefore;

                long t = missPrefix[x - 1];
                long zb = zerosBefore[i];

                long totalCnt = fact[K] * (fixedSmallerAfter % MOD) % MOD;
                if (K > 0) {
                    totalCnt = (totalCnt + t % MOD * zb % MOD * fact[K - 1]) % MOD;
                }

                fixedContribution[i] = totalCnt;
                fwLeft.add(x, 1);
                seenFixed++;
            }
        }

        // For zero positions:
        // S_i = sum_{fixed z after i} (#missing > z)
        // Scan from right to left, maintain weighted sum over fixed values after i.
        long[] zeroContribution = new long[N + 1];
        long weightedFixedAfter = 0; // sum missGreaterThan(z) over fixed z after current i
        for (int i = N; i >= 1; i--) {
            if (a[i] == 0) {
                long totalCnt = 0;
                if (K >= 1) {
                    totalCnt = weightedFixedAfter % MOD * fact[K - 1] % MOD;
                }
                if (K >= 2) {
                    long pairs = (long) K * (K - 1) / 2 % MOD;
                    long zerosAfter = K - zerosBefore[i];
                    totalCnt = (totalCnt + zerosAfter % MOD * fact[K - 2] % MOD * pairs) % MOD;
                }
                zeroContribution[i] = totalCnt;
            } else {
                int z = a[i];
                long missGreater = K - missPrefix[z];
                weightedFixedAfter += missGreater;
                if (weightedFixedAfter >= MOD) weightedFixedAfter -= MOD;
            }
        }

        for (int i = 1; i <= N; i++) {
            long cntSum = (a[i] == 0 ? zeroContribution[i] : fixedContribution[i]);
            ans = (ans + fact[N - i] * cntSum) % MOD;
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
