    // Let S_seen(v) = number of missing values <= v already fixed in previous fixed positions.
    // For a zero at position i with k previous zeros, each missing value appears equally often in each previous zero:
    // total sum of indicator(chosen < x) over all assignments = k * P(Z-1, k-1) * count_missing_less_than_x * (Z-k)! ...
    // We derive a simpler formula below directly in contributions.

    int zerosSeen = 0;

    for (int i = 1; i <= N; ++i) {
        int remPos = N - i;
        if (A[i] != 0) {
            int x = A[i];

            // Number of smaller available values at this position for each completion:
            // smaller missing values not used by previous zero positions and not fixed before.
            // Sum over all completions:
            // part from fixed smaller missing values count M:
            //   each contributes in all Z! completions
            // part subtract previous zero-used smaller values:
            //   for each of zerosSeen previous zero positions, each smaller missing value is used there
            //   in exactly (Z-1)! completions per position
            long long totalMissingLess = fwMissing.sumPrefix(x - 1); // among all missing values
            long long fixedSeenLess = fwFixedSeen.sumPrefix(x - 1);  // fixed values already seen, not actually in missing
            (void)fixedSeenLess; // not needed, kept for clarity

            // smaller available values before x among missing after excluding previous zero choices
            long long countLessMissing = totalMissingLess;

            long long sumSmallerAvail = 0;
            // Start with all smaller missing values counted in all completions
            sumSmallerAvail = countLessMissing % MOD * fact[Z] % MOD;
            // Subtract cases where such value already used in one of previous zero positions
            if (zerosSeen > 0) {
                sumSmallerAvail = (sumSmallerAvail
                    - (countLessMissing % MOD) * zerosSeen % MOD * fact[Z - 1]) % MOD;
            }
            if (sumSmallerAvail < 0) sumSmallerAvail += MOD;

            ans = (ans + sumSmallerAvail * fact[remPos]) % MOD;
            fwFixedSeen.add(x, 1);
        } else {
            // At zero position i:
            // For a completion, chosen value y contributes number of smaller available values:
            //   (# fixed unseen missing < y) + (# missing < y not used by previous zeros)
            // Since only missing values can be chosen/available here, this is:
            //   rank among all missing values of y - 1 - (# previous zero choices < y)
            //
            // Sum over all completions:
            // Sum_y [ (cntLess(y)) * number of completions choosing y here ]
            //  - Sum_y [ (#prevZeroChoices<y) * ... ]
            //
            // Each y is chosen here in (Z-1)! completions.
            // First term:
            //   (Z-1)! * sum_y cntLess(y) over missing y
            // where cntLess(y) is count of missing values < y.
            //
            // If missing values are sorted m[0..Z-1], then cntLess(m[t]) = t.
            // sum t = Z*(Z-1)/2.
            //
            // Second term:
            // For each previous zero position and each ordered pair (u,y) of distinct missing values
            // with u<y, assignments with prev=u and current=y are (Z-2)!.
            // Count of such pairs is C(Z,2), multiplied by zerosSeen previous zero positions.
            //
            long long first = 0;
            if (Z >= 1) {
                first = (1LL * Z * (Z - 1) / 2) % MOD;
                first = first * fact[Z - 1] % MOD;
            }
            long long second = 0;
            if (zerosSeen > 0 && Z >= 2) {
                second = (1LL * Z * (Z - 1) / 2) % MOD;
                second = second * zerosSeen % MOD * fact[Z - 2] % MOD;
            }
            long long sumSmallerAvail = (first - second) % MOD;
            if (sumSmallerAvail < 0) sumSmallerAvail += MOD;

            ans = (ans + sumSmallerAvail * fact[remPos]) % MOD;
            zerosSeen++;
        }
    }

